package dev.gamersclt.batcaverna.nativeapp;
import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,manifest=Config.NONE)
public class PeerActivityTest {
 private JSONObject meta(String ref,String game,String source,long time)throws Exception{return new JSONObject().put("phx_ref",ref).put("jogo",game).put("jogo_fonte",source).put("status","online").put("online_at",time);}
 @Test public void pcActivityWinsOverAnotherDeviceAndNewestEmptyClearsSteam()throws Exception{long now=1000000;JSONObject pc=meta("pc","Minecraft","pc",now-1000),mobile=meta("mobile","Hades","steam",now);assertSame(pc,PeerActivity.current(new JSONArray().put(mobile).put(pc),now));JSONObject closed=meta("pc-new","","",now+1000);assertSame(closed,PeerActivity.current(new JSONArray().put(mobile).put(closed),now+1000));}
 @Test public void staleHiddenAndDisabledSamplesDoNotExposeGames()throws Exception{long now=1000000;assertNull(PeerActivity.current(new JSONArray().put(meta("old","Hades","pc",now-91000)),now));JSONObject hidden=meta("hidden","Secret","pc",now).put("status","invisivel");assertEquals("invisivel",PeerActivity.current(new JSONArray().put(hidden),now).optString("status"));assertFalse(PeerActivity.label(meta("one","Secret","pc",now).put("activity_shared",false)).contains("Secret"));}
 @Test public void refreshedRefsReplaceOldGamesAndIgnoreLateLeaves()throws Exception{JSONObject old=meta("old","Hades","pc",1000),current=meta("new","","",2000).put("phx_ref_prev","old");JSONArray result=PeerActivity.merge(new JSONArray().put(old),new JSONArray().put(current),false);assertEquals(1,result.length());assertSame(current,result.optJSONObject(0));result=PeerActivity.merge(result,new JSONArray().put(old),true);assertEquals(1,result.length());assertSame(current,result.optJSONObject(0));assertEquals(0,PeerActivity.merge(result,new JSONArray().put(current),true).length());}
 @Test public void actualStatusRemainsVisibleWithTheGame()throws Exception{for(String status:new String[]{"ausente","dnd"}){JSONObject sample=meta("one","Celeste","pc",1000).put("status",status);String label=PeerActivity.label(sample);assertTrue(label.contains("Celeste"));assertTrue(label.contains(status.equals("ausente")?"Ausente":"Não incomodar"));}}
}
